type Translator = { locale: Locale; setLocale: (locale: Locale) => void; t: (key: string, values?: Record<string, string | number>) => string };
const LocaleContext = createContext<Translator | null>(null);

export function LocaleProvider({ children }: { children: ReactNode }) {
  const [locale, setLocaleState] = useState<Locale>("en");
  useEffect(() => {
    const saved = window.localStorage.getItem("genetia.locale");
    if (saved && (LOCALES as readonly string[]).includes(saved)) setLocaleState(saved as Locale);
  }, []);
  useEffect(() => { document.documentElement.lang = locale; }, [locale]);
  const setLocale = (next: Locale) => {
    setLocaleState(next);
    window.localStorage.setItem("genetia.locale", next);
  };
  const value = useMemo<Translator>(() => ({
    locale,
    setLocale,
    t: (key, values = {}) => {
      let text = messages[locale][key] ?? messages.en[key] ?? key;
      for (const [name, replacement] of Object.entries(values)) text = text.replaceAll(`{${name}}`, String(replacement));
      return text;
    },
  }), [locale]);
  return <LocaleContext.Provider value={value}>{children}</LocaleContext.Provider>;
}

export function useI18n() {
  const value = useContext(LocaleContext);
  if (!value) throw new Error("useI18n must be used within LocaleProvider");
  return value;
}
